class Solution {
    public List<List<Integer>> permute(int n) {
        List<List<Integer>> res = new ArrayList<>();
        int[] p = new int[n];
        for (int i = 0; i < n; i++) p[i] = i + 1;
        do {
            boolean ok = true;
            for (int i = 0; i + 1 < n; i++)
                if ((p[i] & 1) == (p[i + 1] & 1)) { ok = false; break; }
            if (ok) {
                List<Integer> row = new ArrayList<>();
                for (int x : p) row.add(x);
                res.add(row);
            }
        } while (nextPerm(p));
        return res;
    }
    private boolean nextPerm(int[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i < 0) return false;
        int j = a.length - 1;
        while (a[j] <= a[i]) j--;
        int t = a[i]; a[i] = a[j]; a[j] = t;
        for (int l = i + 1, r = a.length - 1; l < r; l++, r--) {
            t = a[l]; a[l] = a[r]; a[r] = t;
        }
        return true;
    }
}

