var permute = function(n) {
    const res = [];
    const p = Array.from({length: n}, (_, i) => i + 1);
    const nextPerm = () => {
        let i = n - 2;
        while (i >= 0 && p[i] >= p[i + 1]) i--;
        if (i < 0) return false;
        let j = n - 1;
        while (p[j] <= p[i]) j--;
        [p[i], p[j]] = [p[j], p[i]];
        for (let l = i + 1, r = n - 1; l < r; l++, r--) [p[l], p[r]] = [p[r], p[l]];
        return true;
    };
    do {
        let ok = true;
        for (let i = 0; i + 1 < n; i++)
            if (p[i] % 2 === p[i + 1] % 2) { ok = false; break; }
        if (ok) res.push([...p]);
    } while (nextPerm());
    return res;
};

