class Solution:
    def permute(self, n: int) -> List[List[int]]:
        res, cur = [], []
        def dfs(mask, prev):
            if len(cur) == n:
                res.append(cur[:])
                return
            for x in range(1, n + 1):
                if mask >> (x - 1) & 1:
                    continue
                if prev and x % 2 == prev % 2:
                    continue
                cur.append(x)
                dfs(mask | 1 << (x - 1), x)
                cur.pop()
        dfs(0, 0)
        return res

