        if ((int)cur.size() == n) { res.push_back(cur); return; }
        for (int x = 1; x <= n; x++) {
            if (mask >> (x - 1) & 1) continue;
            if (prev && x % 2 == prev % 2) continue;
            cur.push_back(x);
            dfs(mask | 1 << (x - 1), x);
            cur.pop_back();
        }
    }
public:
