class Solution {
    private List<List<Integer>> res = new ArrayList<>();
    private List<Integer> cur = new ArrayList<>();
    private void dfs(int n, int mask, int prev) {
        if (cur.size() == n) { res.add(new ArrayList<>(cur)); return; }
        for (int x = 1; x <= n; x++) {
            if ((mask >> (x - 1) & 1) == 1) continue;
            if (prev != 0 && x % 2 == prev % 2) continue;
            cur.add(x);
            dfs(n, mask | 1 << (x - 1), x);
            cur.remove(cur.size() - 1);
        }
    }
    public List<List<Integer>> permute(int n) {
        dfs(n, 0, 0);
        return res;
    }
}

